00105     public function __construct($id, $type) {
00106         Log::initClass($this);
00107         $this->reload($id, $type);
00108     }
00109 
00116     public function reload($id = null, $type = null) {
00117         global $bearsamppRoot, $bearsamppConfig, $bearsamppBins, $bearsamppLang;
00118         Log::reloadClass($this);
00119 
00120         $this->name = $bearsamppLang->getValue(Lang::PHP);
00121         $this->version = $bearsamppConfig->getRaw(self::ROOT_CFG_VERSION);
00122         parent::reload($id, $type);
00123 
00124         $this->enable = $this->enable && $bearsamppConfig->getRaw(self::ROOT_CFG_ENABLE);
00125         $this->apacheConf = Path::getModuleCurrentPath($bearsamppBins->getApache()) . '/' . $this->apacheConf; //FIXME: Useful ?
00126         $this->errorLog = Path::getLogsPath() . '/php_error.log';
00127 
00128         if ($this->bearsamppConfRaw !== false) {
00129             $this->cliExe = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_CLI_EXE];
00130             $this->cliSilentExe = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_CLI_SILENT_EXE];
00131             $this->conf = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_CONF];
00132             $this->pearExe = $this->symlinkPath . '/' . $this->bearsamppConfRaw[self::LOCAL_CFG_PEAR_EXE];
00133         }
00134 
00135         if (!$this->enable) {
00136             Log::info($this->name . ' is not enabled!');
00137             return;
00138         }
00139         if (!is_dir($this->currentPath)) {
00140             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->currentPath));
00141             return;
00142         }
00143         if (!is_dir($this->symlinkPath)) {
00144             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_FILE_NOT_FOUND), $this->name . ' ' . $this->version, $this->symlinkPath));
00145             return;
00146         }
00147         if (!is_file($this->bearsamppConf)) {
00148             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_CONF_NOT_FOUND), $this->name . ' ' . $this->version, $this->bearsamppConf));
00149             return;
00150         }
00151         if (!is_file($this->cliExe)) {
00152             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_EXE_NOT_FOUND), $this->name . ' ' . $this->version, $this->cliExe));
00153         }
00154         if (!is_file($this->cliSilentExe)) {
00155             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_EXE_NOT_FOUND), $this->name . ' ' . $this->version, $this->cliSilentExe));
00156         }
00157         if (!is_file($this->conf)) {
00158             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_CONF_NOT_FOUND), $this->name . ' ' . $this->version, $this->conf));
00159         }
00160         if (!is_file($this->pearExe)) {
00161             Log::error(sprintf($bearsamppLang->getValue(Lang::ERROR_EXE_NOT_FOUND), $this->name . ' ' . $this->version, $this->pearExe));
00162         }
00163     }
