00172     public function switchVersion($version, $showWindow = false) {
00173         Log::debug('Switch ' . $this->name . ' version to ' . $version);
00174         return $this->updateConfig($version, 0, $showWindow);
00175     }
00176 
00185     protected function updateConfig($version = null, $sub = 0, $showWindow = false) {
00186         global $bearsamppLang, $bearsamppBins, $bearsamppApps, $bearsamppWinbinder;
00187 
00188         if (!$this->enable) {
00189             return true;
00190         }
00191 
00192         $version = $version == null ? $this->version : $version;
00193         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'Update ' . $this->name . ' ' . $version . ' config');
00194 
00195         $boxTitle = sprintf($bearsamppLang->getValue(Lang::SWITCH_VERSION_TITLE), $this->getName(), $version);
00196 
00197         $conf = str_replace('php' . $this->getVersion(), 'php' . $version, $this->getConf());
00198         Log::trace('Current php version found: ' . $conf);
00199         $bearsamppConf = str_replace('php' . $this->getVersion(), 'php' . $version, $this->bearsamppConf);
00200         Log::trace('Current bearsampp.conf php version found: ' . $bearsamppConf);
00201 
00202         $tsDll = $this->getTsDll($version);
00203         $apachePhpModulePath = $this->getApacheModule($bearsamppBins->getApache()->getVersion(), $version);
00204 
00205         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'PHP TsDll found: ' . $tsDll);
00206         Log::debug(($sub > 0 ? str_repeat(' ', 2 * $sub) : '') . 'PHP Apache module found: ' . $apachePhpModulePath);
00207 
00208         if (!file_exists($conf) || !file_exists($bearsamppConf)) {
00209             Log::error('bearsampp config files not found for ' . $this->getName() . ' ' . $version);
00210             if ($showWindow) {
00211                 $bearsamppWinbinder->messageBoxError(
00212                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR), $this->getName() . ' ' . $version),
00213                     $boxTitle
00214                 );
00215             }
00216             return false;
00217         }
00218 
00219         $bearsamppConfRaw = parse_ini_file($bearsamppConf);
00220         if ($bearsamppConfRaw === false || !isset($bearsamppConfRaw[self::ROOT_CFG_VERSION]) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version) {
00221             Log::error('bearsampp config file malformed for ' . $this->getName() . ' ' . $version);
00222             if ($showWindow) {
00223                 $bearsamppWinbinder->messageBoxError(
00224                     sprintf($bearsamppLang->getValue(Lang::BEARSAMPP_CONF_MALFORMED_ERROR), $this->getName() . ' ' . $version),
00225                     $boxTitle
00226                 );
00227             }
00228             return false;
00229         }
00230 
00231         if ($tsDll === false || $apachePhpModulePath === false) {
00232             Log::debug($this->getName() . ' ' . $version . ' does not seem to be compatible with Apache ' . $bearsamppBins->getApache()->getVersion());
00233             if ($showWindow) {
00234                 $bearsamppWinbinder->messageBoxError(
00235                     sprintf($bearsamppLang->getValue(Lang::PHP_INCPT), $version, $bearsamppBins->getApache()->getVersion()),
00236                     $boxTitle
00237                 );
00238             }
00239             return false;
00240         }
00241 
00242         // bearsampp.conf
00243         Log::trace('Calling Set Version for php...');
00244         $this->setVersion($version);
00245 
00246         // conf
00247         Util::replaceInFile($this->getConf(), array(
00248             '/^mysql.default_port\s=\s(\d+)/' => 'mysql.default_port = ' . $bearsamppBins->getMysql()->getPort(),
00249             '/^mysqli.default_port\s=\s(\d+)/' => 'mysqli.default_port = ' . $bearsamppBins->getMysql()->getPort()
00250         ));
00251 
00252         // apache
00253         $bearsamppBins->getApache()->update($sub + 1);
00254 
00255         // phpmyadmin
00256         $bearsamppApps->getPhpmyadmin()->update($sub + 1);
00257 
00258         return true;
00259     }
