00456     public function isSettingActive($name) {
00457         $settingsValues = $this->getSettingsValues();
00458 
00459         $confContent = file($this->getConf());
00460         foreach ($confContent as $row) {
00461             $settingMatch = array();
00462             if (preg_match('/^' . $name . '\s*=\s*(.+)/i', $row, $settingMatch)) {
00463                 return isset($settingMatch[1]) && isset($settingsValues[$name]) && $settingsValues[$name][0] == trim($settingMatch[1]);
00464             }
00465         }
00466 
00467         return false;
00468     }
