00506     private function isExtensionExcluded($ext) {
00507         return in_array($ext, array(
00508             'opcache',
00509             'xdebug'
00510         ));
00511     }
00512 
00518     public function getExtensionsFromConf() {
00519         $result = array();
00520 
00521         $confContent = file($this->getConf());
00522         foreach ($confContent as $row) {
00523             $extMatch = array();
00524             if (preg_match('/^(;)?extension\s*=\s*"?(.+)"?/i', $row, $extMatch)) {
00525                 $name = preg_replace("/^php_/", "", preg_replace("/\.dll$/", "", trim($extMatch[2])));
00526                 if ($this->isExtensionExcluded($name)) {
00527                     continue;
00528                 }
00529                 if ($extMatch[1] == ';') {
00530                     $result[$name] = ActionSwitchPhpExtension::SWITCH_OFF;
00531                 } else {
00532                     $result[$name] = ActionSwitchPhpExtension::SWITCH_ON;
00533                 }
00534             }
00535         }
00536 
00537         ksort($result);
00538         return $result;
00539     }
00540 
00546     public function getExtensionsLoaded() {
00547         $result = array();
00548         foreach ($this->getExtensionsFromConf() as $name => $status) {
00549             if ($status == ActionSwitchPhpExtension::SWITCH_ON) {
00550                 $result[] = $name;
00551             }
00552         }
00553         return $result;
00554     }
00555 
00561     public function getExtensionsFromFolder() {
00562         $result = array();
00563 
00564         $handle = @opendir(Path::getModuleCurrentPath($this). '/ext');
00565         if (!$handle) {
00566             return $result;
00567         }
00568 
00569         while (false !== ($file = readdir($handle))) {
00570             if ($file != "." && $file != ".." && UtilString::endWith($file, '.dll')) {
00571                 $name = preg_replace("/^php_/", "", preg_replace("/\.dll$/", "", trim($file)));
00572                 if ($this->isExtensionExcluded($name)) {
00573                     continue;
00574                 }
00575                 $result[$name] = ActionSwitchPhpExtension::SWITCH_OFF;
00576             }
00577         }
00578 
00579         closedir($handle);
00580         ksort($result);
00581         return $result;
00582     }
