00591     public function getApacheModule($apacheVersion, $phpVersion = null) {
00592         $apacheVersion = substr(str_replace('.', '', $apacheVersion), 0, 2);
00593         $phpVersion = $phpVersion == null ? $this->getVersion() : $phpVersion;
00594 
00595         $currentPath = str_replace('php' . $this->getVersion(), 'php' . $phpVersion, Path::getModuleCurrentPath($this));
00596         $bearsamppConf = str_replace('php' . $this->getVersion(), 'php' . $phpVersion, $this->bearsamppConf);
00597 
00598         if (in_array($phpVersion, $this->getVersionList()) && file_exists($bearsamppConf)) {
00599             $apacheCpt = parse_ini_file($bearsamppConf);
00600             if ($apacheCpt !== false) {
00601                 foreach ($apacheCpt as $aVersion => $apacheModule) {
00602                     $aVersion = str_replace('apache', '', $aVersion);
00603                     $aVersion = str_replace('.', '', $aVersion);
00604                     if ($apacheVersion == $aVersion && file_exists($currentPath . '/' . $apacheModule)) {
00605                         return $currentPath . '/' . $apacheModule;
00606                     }
00607                 }
00608             }
00609         }
00610 
00611         return false;
00612     }
