00620     public function getTsDll($phpVersion = null) {
00621         $phpVersion = $phpVersion == null ? $this->getVersion() : $phpVersion;
00622         $currentPath = str_replace('php' . $this->getVersion(), 'php' . $phpVersion, Path::getModuleCurrentPath($this));
00623 
00624         if (file_exists($currentPath . '/php7ts.dll')) {
00625             return 'php7ts.dll';
00626         } elseif (file_exists($currentPath . '/php8ts.dll')) {
00627             return 'php8ts.dll';
00628         }
00629 
00630         return false;
00631     }
