00654     public function setEnable($enabled, $showWindow = false) {
00655         global $bearsamppConfig, $bearsamppBins, $bearsamppLang, $bearsamppWinbinder;
00656 
00657         if ($enabled == Config::ENABLED && !is_dir($this->currentPath)) {
00658             Log::debug($this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath);
00659             if ($showWindow) {
00660                 $bearsamppWinbinder->messageBoxError(
00661                     sprintf($bearsamppLang->getValue(Lang::ENABLE_BUNDLE_NOT_EXIST), $this->getName(), $this->getVersion(), $this->currentPath),
00662                     sprintf($bearsamppLang->getValue(Lang::ENABLE_TITLE), $this->getName())
00663                 );
00664             }
00665             $enabled = Config::DISABLED;
00666         }
00667 
00668         Log::info($this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled'));
00669         $this->enable = $enabled == Config::ENABLED;
00670         $bearsamppConfig->replace(self::ROOT_CFG_ENABLE, $enabled);
00671 
00672         $this->reload();
00673         $bearsamppBins->getApache()->update();
00674         if ($bearsamppBins->getApache()->isEnable() && $bearsamppBins->getApache()->getService()->isRunning()) {
00675             $bearsamppBins->getApache()->getService()->stop();
00676             Util::startService($bearsamppBins->getApache(), BinApache::CMD_SYNTAX_CHECK, $showWindow);
00677         }
00678     }
